insert into public.cars (slug,name,year,engine,km,country,price,status,description) values ('porsche-911-carrera-993','Porsche 911 Carrera (993)',1995,'3.6 Flat-6 air-cooled · 272 CV',86400,'California, USA','Su richiesta','Disponibile','L''ultima 911 raffreddata ad aria. Esemplare unico proprietario, tagliandi documentati Porsche, matching numbers. Vernice Riviera Blue originale, interni in pelle nera senza difetti.') on conflict (slug) do nothing;
insert into public.car_photos (car_id,url,sort) select id,u,s from public.cars, (values ('assets/img/cars/porsche-993-1.jpg',0),('assets/img/cars/porsche-993-2.jpg',1),('assets/img/cars/porsche-993-3.jpg',2)) v(u,s) where slug='porsche-911-carrera-993' and not exists (select 1 from public.car_photos p where p.car_id=cars.id);
insert into public.cars (slug,name,year,engine,km,country,price,status,description) values ('chevrolet-corvette-c6','Chevrolet Corvette C6',2007,'V8 6.0 LS2 · 404 CV',52300,'Texas, USA','Su richiesta','Disponibile','Corvette C6 con cambio manuale a 6 rapporti e pacchetto Z51. Sempre in garage climatizzato, mai pista. Gomme nuove e batteria sostituita a giugno 2026.') on conflict (slug) do nothing;
insert into public.car_photos (car_id,url,sort) select id,u,s from public.cars, (values ('assets/img/cars/corvette-c6-1.jpg',0),('assets/img/cars/corvette-c6-2.jpg',1),('assets/img/cars/corvette-c6-3.jpg',2)) v(u,s) where slug='chevrolet-corvette-c6' and not exists (select 1 from public.car_photos p where p.car_id=cars.id);
insert into public.cars (slug,name,year,engine,km,country,price,status,description) values ('dodge-viper-srt10','Dodge Viper SRT-10',2006,'V10 8.3 · 517 CV',31800,'Florida, USA','Su richiesta','In arrivo','Dieci cilindri di pura analogia americana. Scarico laterale originale, nessuna modifica. Libretto service completo e due set di chiavi. Una delle ultime SRT-10 prima del restyling.') on conflict (slug) do nothing;
insert into public.car_photos (car_id,url,sort) select id,u,s from public.cars, (values ('assets/img/cars/dodge-viper-1.jpg',0),('assets/img/cars/dodge-viper-2.jpg',1),('assets/img/cars/dodge-viper-3.jpg',2)) v(u,s) where slug='dodge-viper-srt10' and not exists (select 1 from public.car_photos p where p.car_id=cars.id);
insert into public.cars (slug,name,year,engine,km,country,price,status,description) values ('ford-gt','Ford GT',2005,'V8 5.4 Supercharged · 558 CV',18900,'Michigan, USA','Su richiesta','Disponibile','L''erede della leggenda di Le Mans. Primo anno di produzione, tutti gli optional factory inclusi. Manutenzione eseguita solo presso Ford GT certified shop. Da collezione.') on conflict (slug) do nothing;
insert into public.car_photos (car_id,url,sort) select id,u,s from public.cars, (values ('assets/img/cars/ford-gt-1.jpg',0),('assets/img/cars/ford-gt-2.jpg',1),('assets/img/cars/ford-gt-3.jpg',2)) v(u,s) where slug='ford-gt' and not exists (select 1 from public.car_photos p where p.car_id=cars.id);
insert into public.cars (slug,name,year,engine,km,country,price,status,description) values ('shelby-gt500','Ford Mustang Shelby GT500',2021,'V8 5.2 Predator · 771 CV',12400,'Nevada, USA','Su richiesta','Disponibile','La Mustang più potente di sempre. Cambio doppia frizione Tremec a 7 rapporti, pacchetto Carbon Fiber Track Pack. Praticamente nuova, ancora in garanzia ufficiale USA.') on conflict (slug) do nothing;
insert into public.car_photos (car_id,url,sort) select id,u,s from public.cars, (values ('assets/img/cars/shelby-gt500-1.jpg',0),('assets/img/cars/shelby-gt500-2.jpg',1),('assets/img/cars/shelby-gt500-3.jpg',2)) v(u,s) where slug='shelby-gt500' and not exists (select 1 from public.car_photos p where p.car_id=cars.id);
insert into public.cars (slug,name,year,engine,km,country,price,status,description) values ('harley-davidson-sportster-iron-883','Harley-Davidson Sportster Iron 883',2022,'V-Twin Evolution 883 cc · 52 CV',2400,'Wisconsin, USA','Su richiesta','Disponibile','Il V-Twin di Milwaukee nel suo formato più essenziale: serbatoio peanut, scarico nero e sound inconfondibile. Esemplare in ottime condizioni, tagliandi documentati. Foto da concessionario a scopo illustrativo.') on conflict (slug) do nothing;
