insert into public.cars (slug,name,year,engine,km,country,price,status,description) values ('buell-rr1000-battletwin','Buell RR1000 Battletwin',1987,'V-Twin 1000 cc · 75 CV',5800,'Wisconsin, USA','Su richiesta','Disponibile','Rarità americana degli anni ''80: la Buell da record, con la carenatura integrale e il telaio che l''hanno resa un cult. Esemplare conservato, documenti in regola. Foto da concessionario a scopo illustrativo.') on conflict (slug) do nothing;
